/* 状态模拟：原规则是 .title:is(:hover, :focus-visible) 上两条 100ms 的 opacity 切换，
   这里用 .forceHover 静态触发；标题色的 hover 变化一并搬过来。 */
.title.forceHover { color: var(--dsw-alias-label-secondary); }
.title.forceHover .activityIcon { opacity: 0; }
.title.forceHover .chevron { opacity: 1; }

/* 状态模拟：真实规则是 .compactionButton:not(:disabled):hover 上的字形交叉淡入与
   --dsw-alias-interactive-bg-hover 底色，这里用 .forceHover 静态触发。 */
.compactionButton.forceHover { color: var(--dsw-alias-label-secondary); background: var(--dsw-alias-interactive-bg-hover); }
.compactionButton.forceHover .compactionContextIcon { opacity: 0; }
.compactionButton.forceHover .compactionDisclosureIcon { opacity: 1; }
